base.strided.unaryBy( arrays, shape, strides, fcn, clbk[, thisArg] )
    Applies a unary function to each element retrieved from a strided input
    array according to a callback function and assigns results to a strided
    output array.

    The shape and stride parameters determine which elements in the strided
    input and output arrays are accessed at runtime.

    Indexing is relative to the first index. To introduce an offset, use typed
    array views.

    The callback function is provided four arguments:

    - value: array element.
    - idx: iteration index.
    - indices: strided indices (offset + idx*stride).
    - arrays: input and output arrays.

    If the callback function does not return any value (or equivalently,
    explicitly returns `undefined`), the value is ignored.

    Parameters
    ----------
    arrays: ArrayLikeObject<ArrayLikeObject>
        Array-like object containing one strided input array and one strided
        output array.

    shape: ArrayLikeObject<integer>
        Array-like object containing a single element, the number of indexed
        elements.

    strides: ArrayLikeObject<integer>
        Array-like object containing the stride lengths for the strided input
        and output arrays.

    fcn: Function
        Unary function to apply to callback return values.

    clbk: Function
        Callback function.

    thisArg: any (optional)
        Callback execution context.

    Examples
    --------
    // Standard usage:
    > var x = [ 1.0, -2.0, 3.0, -4.0 ];
    > var y = [ 0.0, 0.0, 0.0, 0.0 ];
    > var sh = [ x.length ];
    > var st = [ 1, 1 ];
    > function clbk( v ) { return v * 2.0; };
    > base.strided.unaryBy( [ x, y ], sh, st, base.abs, clbk );
    > y
    [ 2.0, 4.0, 6.0, 8.0 ]

    // Using shape and stride parameters:
    > y = [ 0.0, 0.0, 0.0, 0.0 ];
    > sh = [ 2 ];
    > st = [ 2, -1 ];
    > base.strided.unaryBy( [ x, y ], sh, st, base.abs, clbk );
    > y
    [ 6.0, 2.0, 0.0, 0.0 ]

    // Using view offsets:
    > var x0 = new Float64Array( [ 1.0, -2.0, 3.0, -4.0 ] );
    > var y0 = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
    > var x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );
    > var y1 = new Float64Array( y0.buffer, y0.BYTES_PER_ELEMENT*2 );
    > sh = [ 2 ];
    > st = [ -2, 1 ];
    > base.strided.unaryBy( [ x1, y1 ], sh, st, base.abs, clbk );
    > y1
    <Float64Array>[ 8.0, 4.0 ]
    > y0
    <Float64Array>[ 0.0, 0.0, 8.0, 4.0 ]


base.strided.unaryBy.ndarray( arrays, shape, strides, offsets, fcn, clbk[, thisArg] )
    Applies a unary function to each element retrieved from a strided input
    array according to a callback function and assigns results to a strided
    output array using alternative indexing semantics.

    While typed array views mandate a view offset based on the underlying
    buffer, the offsest parameters support indexing semantics
    based on starting indices.

    Parameters
    ----------
    arrays: ArrayLikeObject<ArrayLikeObject>
        Array-like object containing one strided input array and one strided
        output array.

    shape: ArrayLikeObject<integer>
        Array-like object containing a single element, the number of indexed
        elements.

    strides: ArrayLikeObject<integer>
        Array-like object containing the stride lengths for the strided input
        and output arrays.

    offsets: ArrayLikeObject<integer>
        Array-like object containing the starting indices (i.e., index offsets)
        for the strided input and output arrays.

    fcn: Function
        Unary function to apply to callback return values.

    clbk: Function
        Callback function.

    thisArg: any (optional)
        Callback execution context.

    Examples
    --------
    // Standard usage:
    > var x = [ 1.0, -2.0, 3.0, -4.0 ];
    > var y = [ 0.0, 0.0, 0.0, 0.0 ];
    > var sh = [ x.length ];
    > var st = [ 1, 1 ];
    > var o = [ 0, 0 ];
    > function clbk( v ) { return v * 2.0; };
    > base.strided.unaryBy.ndarray( [ x, y ], sh, st, o, base.abs, clbk );
    > y
    [ 2.0, 4.0, 6.0, 8.0 ]

    // Advanced indexing:
    > x = [ 1.0, -2.0, 3.0, -4.0 ];
    > y = [ 0.0, 0.0, 0.0, 0.0 ];
    > sh = [ 2 ];
    > st = [ 2, -1 ];
    > o = [ 1, y.length-1 ];
    > base.strided.unaryBy.ndarray( [ x, y ], sh, st, o, base.abs, clbk );
    > y
    [ 0.0, 0.0, 8.0, 4.0 ]

    See Also
    --------
    base.strided.mapBy, base.strided.unary

base.sumSeries( generator[, options] )
    Sum the elements of the series given by the supplied function.

    Parameters
    ----------
    generator: Function
        Series function.

    options: Object (optional)
        Options.

    options.maxTerms: integer (optional)
        Maximum number of terms to be added. Default: `1000000`.

    options.tolerance: number (optional)
        Further terms are only added as long as the next term is greater than
        the current term times the tolerance. Default: `2.22e-16`.

    options.initialValue: number (optional)
        Initial value of the resulting sum. Default: `0`.

    Returns
    -------
    out: number
        Sum of series terms.

    Examples
    --------
    // Using an ES6 generator function:
    > function* geometricSeriesGenerator( x ) {
    ...     var exponent = 0;
    ...     while ( true ) {
    ...         yield Math.pow( x, exponent );
    ...         exponent += 1;
    ...     }
    ... };
    > var gen = geometricSeriesGenerator( 0.9 );
    > var out = base.sumSeries( gen )
    10

    // Using a closure:
    > function geometricSeriesClosure( x ) {
    ...     var exponent = -1;
    ...     return function() {
    ...         exponent += 1;
    ...         return Math.pow( x, exponent );
    ...     };
    ... };
    > gen = geometricSeriesClosure( 0.9 );
    > out = base.sumSeries( gen )
    10

    // Setting an initial value for the sum:
    > out = base.sumSeries( geometricSeriesGenerator( 0.5 ), { 'initialValue': 1 } )
    3
    // Changing the maximum number of terms to be summed:
    > out = base.sumSeries( geometricSeriesGenerator( 0.5 ), { 'maxTerms': 10 } )
    ~1.998 // Infinite sum is 2

    // Adjusting the used tolerance:
    > out = base.sumSeries( geometricSeriesGenerator( 0.5 ), { 'tolerance': 1e-3 } )
    ~1.998

bifurcateByAsync( collection, [options,] predicate, done )
    Splits values into two groups according to a predicate function.

    When invoked, the predicate function is provided a maximum of four
    arguments:

    - value: collection value.
    - index: collection index.
    - collection: the input collection.
    - next: a callback to be invoked after processing a collection `value`.

    The actual number of provided arguments depends on function length. If the
    predicate function accepts two arguments, the predicate function is
    provided:

    - value
    - next

    If the predicate function accepts three arguments, the predicate function is
    provided:

    - value
    - index
    - next

    For every other predicate function signature, the predicate function is
    provided all four arguments.

    The `next` callback takes two arguments:

    - error: error argument.
    - group: value group.

    If an predicate function calls the `next` callback with a truthy `error`
    argument, the function suspends execution and immediately calls the `done`
    callback for subsequent `error` handling.

    If a predicate function calls the `next` callback with a truthy group value,
    a collection value is placed in the first group; otherwise, a collection
    value is placed in the second group.

    If provided an empty collection, the function calls the `done` callback with
    an empty array as the second argument.

    Execution is *not* guaranteed to be asynchronous. To guarantee asynchrony,
    wrap the `done` callback in a function which either executes at the end of
    the current stack (e.g., `nextTick`) or during a subsequent turn of the
    event loop (e.g., `setImmediate`, `setTimeout`).

    The function does not support dynamic collection resizing.

    The function does not skip `undefined` elements.

    Parameters
    ----------
    collection: Array|TypedArray|Object
        Input collection over which to iterate. If provided an object, the
        object must be array-like (excluding strings and functions).

    options: Object (optional)
        Function options.

    options.limit: integer (optional)
        Maximum number of pending invocations. Default: Infinity.

    options.series: boolean (optional)
        Boolean indicating whether to process each collection element
        sequentially. Default: false.

    options.returns: string (optional)
        If `values`, values are returned; if `indices`, indices are returned; if
        `*`, both indices and values are returned. Default: 'values'.

    options.thisArg: any (optional)
        Execution context.

    predicate: Function
        Predicate function indicating which group an element in the input
        collection belongs to.

    done: Function
        A callback invoked either upon processing all collection elements or
        upon encountering an error.

    Examples
    --------
    // Basic usage:
    > function predicate( value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, ( index%2 === 0 ) );
    ...     }
    ... };
    > function done( error, result ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( result );
    ... };
    > var arr = [ 3000, 2500, 1000 ];
    > bifurcateByAsync( arr, predicate, done )
    1000
    2500
    3000
    [ [ 1000, 3000 ], [ 2500 ] ]

    // Output group results as indices:
    > var opts = { 'returns': 'indices' };
    > bifurcateByAsync( arr, opts, predicate, done )
    1000
    2500
    3000
    [ [ 2, 0 ], [ 1 ] ]

    // Output group results as index-value pairs:
    > opts = { 'returns': '*' };
    > bifurcateByAsync( arr, opts, predicate, done )
    1000
    2500
    3000
    [ [ [ 2, 1000 ], [ 0, 3000 ] ], [ [ 1, 2500 ] ] ]

    // Limit number of concurrent invocations:
    > function predicate( value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, ( index%2 === 0 ) );
    ...     }
    ... };
    > function done( error, result ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( result );
    ... };
    > var opts = { 'limit': 2 };
    > var arr = [ 3000, 2500, 1000 ];
    > bifurcateByAsync( arr, opts, predicate, done )
    2500
    3000
    1000
    [ [ 3000, 1000 ], [ 2500 ] ]

    // Process sequentially:
    > function predicate( value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, ( index%2 === 0 ) );
    ...     }
    ... };
    > function done( error, result ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( result );
    ... };
    > var opts = { 'series': true };
    > var arr = [ 3000, 2500, 1000 ];
    > bifurcateByAsync( arr, opts, predicate, done )
    3000
    2500
    1000
    [ [ 3000, 1000 ], [ 2500 ] ]


