        A function which tests each element in a collection.

    Examples
    --------
    > function predicate( value, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, true );
    ...     }
    ... };
    > var opts = { 'series': true };
    > var f = everyByRightAsync.factory( opts, predicate );
