groupByAsync.factory( [options,] indicator )
    Returns a function which groups values according to an indicator function.

    Parameters
    ----------
    options: Object (optional)
        Function options.

    options.limit: integer (optional)
        Maximum number of pending invocations. Default: Infinity.

    options.series: boolean (optional)
        Boolean indicating whether to process each collection element
        sequentially. Default: false.

    options.returns: string (optional)
        If `values`, values are returned; if `indices`, indices are returned; if
        `*`, both indices and values are returned. Default: 'values'.

    options.thisArg: any (optional)
        Execution context.

    indicator: Function
        Indicator function specifying which group an element in the input
        collection belongs to.

    Returns
    -------
    out: Function
        A group-by function.

    Examples
    --------
    > function indicator( value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, ( index%2 === 0 ) );
    ...     }
    ... };
    > var opts = { 'series': true };
    > var f = groupByAsync.factory( opts, indicator );
    > function done( error, result ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( result );
    ... };
    > var arr = [ 3000, 2500, 1000 ];
    > f( arr, done )
    3000
    2500
    1000
    { 	rue": [ 3000

groupIn( obj, [options,] indicator )
    Group values according to an indicator function.

    When invoked, the indicator function is provided two arguments:

    - value: object value.
    - key: object key.

    The value returned by an indicator function should be a value which can be
    serialized as an object key.

    If provided an empty object with no prototype, the function returns an empty
    object.

    The function iterates over an object's own and inherited properties.

    Key iteration order is *not* guaranteed, and, thus, result order is *not*
    guaranteed.

    Parameters
    ----------
    obj: Object|Array|TypedArray
        Input object to group.

    options: Object (optional)
        Options.

    options.thisArg: any (optional)
        Execution context.

    options.returns: string (optional)
        If `values`, values are returned; if `keys`, keys are returned; if `*`,
        both keys and values are returned. Default: 'values'.

    indicator: Function
        Indicator function indicating which group a value in the input object
        belongs to.

    Returns
    -------
    out: Object
        Group results.

    Examples
    --------
    > function indicator( v ) {
    ...     if ( v[ 0 ] === 'b' ) {
    ...         return 'b';
    ...     }
    ...     return 'other';
    ... };
    > function Foo() { this.a = 'beep'; this.b = 'boop'; return this; };
    > Foo.prototype = Object.create( null );
    > Foo.prototype.c = 'foo';
    > Foo.prototype.d = 'bar';
    > var obj = new Foo();
    > var out = groupIn( obj, indicator )
    { 'b': [ 'beep', 'boop', 'bar' ], 'other': [ 'foo' ] }

    // Output group results as keys:
    > var opts = { 'returns': 'keys' };
    > out = groupIn( obj, opts, indicator )
    { 'b': [ 'a', 'b', 'd' ], 'other': [ 'c' ] }

    // Output group results as key-value pairs:
    > opts = { 'returns': '*' };
    > out = groupIn( obj, opts, indicator )
    { 'b': [['a','beep'], ['b','boop'], ['d','bar']], 'other': [['c','foo' ]] }

    See Also
    --------
    bifurcateIn, groupBy, groupOwn

ifthenAsync( predicate, x, y, done )
    If a predicate function returns a truthy value, invokes `x`; otherwise,
    invokes `y`.

    The predicate function is provided a single argument:

    - clbk: callback to invoke upon predicate function completion.

    The predicate function callback accepts two arguments:

    - error: error object.
    - bool: condition used to determine whether to invoke `x` or `y`.

    Both `x` and `y` are provided a single argument:

    - clbk: callback to invoke upon function completion.

    The callback function accepts any number of arguments, with the first
    argument reserved for providing an error.

    If the error argument is falsy, the `done` callback is invoked with its
    first argument as `null` and all other provided arguments.

    If the error argument is truthy, the `done` callback is invoked with only an
    error argument.

    Execution is *not* guaranteed to be asynchronous. To guarantee asynchrony,
    wrap the `done` callback in a function which either executes at the end of
    the current stack (e.g., `nextTick`) or during a subsequent turn of the
    event loop (e.g., `setImmediate`, `setTimeout`).

    Parameters
    ----------
    predicate: Function
        Predicate function.

    x: Function
        Function to invoke if a condition is truthy.

    y: Function
        Function to invoke if a condition is falsy.

    done: Function
        Callback to invoke upon completion.

    Examples
    --------
    > function predicate( clbk ) {
    ...     setTimeout( onTimeout, 0 );
    ...     function onTimeout() {
    ...         clbk( null, false );
    ...     }
    ... };
    > function x( clbk ) {
    ...     setTimeout( onTimeout, 0 );
    ...     function onTimeout() {
    ...         clbk( null, 'beep' );
    ...     }
    ... };
    > function y( clbk ) {
    ...     setTimeout( onTimeout, 0 );
    ...     function onTimeout() {
    ...         clbk( null, 'boop' );
    ...     }
    ... };
    > function done( error, result ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( result );
    ... };
    > ifthenAsync( predicate, x, y, done )
    'boop'

    See Also
    --------
    ifelseAsync, ifthen

inmapAsync( collection, [options,] fcn, done )
    Invokes a function once for each element in a collection and updates a
    collection in-place.

    When invoked, `fcn` is provided a maximum of four arguments:

    - value: collection value.
    - index: collection index.
    - collection: the input collection.
    - next: a callback to be invoked after processing a collection `value`.

    The actual number of provided arguments depends on function length. If `fcn`
    accepts two arguments, `fcn` is provided:

    - value
    - next

    If `fcn` accepts three arguments, `fcn` is provided:

    - value
    - index
    - next

    For every other `fcn` signature, `fcn` is provided all four arguments.

    The `next` callback accepts two arguments:

    - error: error argument.
    - result: value used to update the collection.

    If a provided function calls the `next` callback with a truthy `error`
    argument, the function suspends execution and immediately calls the `done`
    callback for subsequent `error` handling. Note, however, that the function
    may have mutated an input collection during prior invocations, resulting in
    a partially mutated collection.

    Execution is *not* guaranteed to be asynchronous. To guarantee asynchrony,
    wrap the `done` callback in a function which either executes at the end of
    the current stack (e.g., `nextTick`) or during a subsequent turn of the
    event loop (e.g., `setImmediate`, `setTimeout`).

    The function does not support dynamic collection resizing.

    The function does not skip `undefined` elements.

    Parameters
    ----------
    collection: Array|TypedArray|Object
        Input collection over which to iterate. If provided an object, the
        object must be array-like (excluding strings and functions).

    options: Object (optional)
        Function options.

    options.limit: integer (optional)
        Maximum number of pending invocations. Default: Infinity.

    options.series: boolean (optional)
        Boolean indicating whether to process each collection element
        sequentially. Default: false.

    options.thisArg: any (optional)
        Execution context.

    fcn: Function
        The function to invoke for each element in a collection.

    done: Function
        A callback invoked either upon processing all collection elements or
        upon encountering an error.

    Examples
    --------
    // Basic usage:
    > function fcn( value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, value*index );
    ...     }
    ... };
    > function done( error, collection ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( collection === arr );
    ...     console.log( collection );
    ... };
    > var arr = [ 3000, 2500, 1000 ];
    > inmapAsync( arr, fcn, done )
    1000
    2500
    3000
    true
    [ 0, 2500, 2000 ]

    // Limit number of concurrent invocations:
    > function fcn( value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, value*index );
    ...     }
    ... };
    > function done( error, collection ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( collection === arr );
    ...     console.log( collection );
    ... };
    > var opts = { 'limit': 2 };
    > var arr = [ 3000, 2500, 1000 ];
    > inmapAsync( arr, opts, fcn, done )
    2500
    3000
    1000
    true
    [ 0, 2500, 2000 ]

    // Process sequentially:
    > function fcn( value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, value*index );
    ...     }
    ... };
    > function done( error, collection ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( collection === arr );
    ...     console.log( collection );
    ... };
    > var opts = { 'series': true };
    > var arr = [ 3000, 2500, 1000 ];
    > inmapAsync( arr, opts, fcn, done )
    3000
    2500
    1000
    true
    [ 0, 2500, 2000 ]


inmapAsync.factory( [options,] fcn )
    Returns a function which invokes a function once for each element in a
    collection and updates a collection in-place.

    Parameters
