random.strided.bernoulli.state
    Generator state.

    Examples
    --------
    > var out = azeros( 3, 'generic' );
    > random.strided.bernoulli( out.length, [ 0.5 ], 0, out, 1 )
    [...]

    // Get a copy of the current state:
    > var state = random.strided.bernoulli.state
    <Uint32Array>

    // Advance the generator state:
    > out = azeros( 3, 'generic' );
    > random.strided.bernoulli( out.length, [ 0.5 ], 0, out, 1 )
    [...]
    > out = azeros( 3, 'generic' );
    > random.strided.bernoulli( out.length, [ 0.5 ], 0, out, 1 )
    [...]

    // Set the state:
    > random.strided.bernoulli.state = state;

    // Regenerate previous generated values:
    > out = azeros( 3, 'generic' );
    > random.strided.bernoulli( out.length, [ 0.5 ], 0, out, 1 )
    [...]

