    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( acc.sum );
    ... };
    > var arr = [ 1000, 2500, 3000 ];
    > var acc = { 'sum': 0 };
    > f( arr, acc, done )
    1000
    2500
    3000
    6500
    > acc = { 'sum': 0 };
    > arr = [ 1000, 1500, 2000 ];
    > f( arr, acc, done )
    1000
    1500
    2000
    4500

    See Also
    --------
    forEachRightAsync, reduceAsync, reduceRight

reduceRightAsync.factory( [options,] fcn )
    Returns a function which applies a function against an accumulator and each
    element in a collection and returns the accumulated result, iterating from
    right to left.

    Parameters
    ----------
    options: Object (optional)
        Function options.

    options.limit: integer (optional)
        Maximum number of pending invocations. Default: Infinity.

    options.series: boolean (optional)
        Boolean indicating whether to process each collection element
        sequentially. Default: true.

    options.thisArg: any (optional)
        Execution context.

    fcn: Function
        The function to invoke for each element in a collection.

    Returns
    -------
    out: Function
        A function which invokes a function for each element in a collection.

    Examples
    --------
    > function fcn( acc, value, index, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         acc.sum += value;
    ...         next( null, acc );
    ...     }
    ... };
    > var opts = { 'series': false };
    > var f = reduceRightAsync.factory( opts, fcn );
    > function done( error, acc ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( acc.sum );
    ... };
    > var arr = [ 1000, 2500, 3000 ];
    > var acc = { 'sum': 0 };
    > f( arr, acc, done )
    1000
    2500
    3000
    6500
    > acc = { 'sum': 0 };
    > arr = [ 1000, 1500, 2000 ];
    > f( arr, acc, done )
    1000
    1500
    2000
    4500

    See Also
    --------
    forEachRightAsync, reduceAsync, reduceRight

shuffle.factory( [options] )
    Returns a function to shuffle elements of array-like objects.

    Parameters
    ----------
    options: Object (optional)
        Options.

    options.seed: integer (optional)
        Integer-valued seed.

    options.copy: string (optional)
        String indicating whether to return a copy (`deep`,`shallow` or `none`).
        Default: `'shallow'`.

    Returns
    -------
    fcn: Function
        Shuffle function.

    Examples
    --------
    > var myshuffle = shuffle.factory();

    // Set a seed:
    > myshuffle = shuffle.factory({ 'seed': 239 });
    > var arr = [ 0, 1, 2, 3, 4 ];
    > var out = myshuffle( arr )
    e.g., [ 3, 4, 1, 0, 2 ]

    // Use a different copy strategy:
    > myshuffle = shuffle.factory({ 'copy': 'none', 'seed': 867 });

    // Created shuffle function mutates input array by default:
    > arr = [ 1, 2, 3, 4, 5, 6 ];
    > out = myshuffle( arr );
    > var bool = ( arr === out )
    true
    // Default option can be overridden:
    > arr = [ 1, 2, 3, 4 ];
    > out = myshuffle( arr, { 'copy': 'shallow' } );
    > bool = ( arr === out )
    false

    See Also
    --------
    sample

someByAsync( collection, n, [options,] predicate, done )
    Tests whether a collection contains at least `n` elements which pass a test
    implemented by a predicate function.

    When invoked, the predicate function is provided a maximum of four
    arguments:

    - value: collection value.
    - index: collection index.
    - collection: the input collection.
    - next: a callback to be invoked after processing a collection `value`.

    The actual number of provided arguments depends on function length. If the
    predicate function accepts two arguments, the predicate function is
    provided:

    - value
    - next

    If the predicate function accepts three arguments, the predicate function is
    provided:

    - value
    - index
    - next

    For every other predicate function signature, the predicate function is
    provided all four arguments.

    The `next` callback takes two arguments:

    - error: error argument.
    - result: test result.

    If a provided function calls the `next` callback with a truthy `error`
    argument, the function suspends execution and immediately calls the `done`
    callback for subsequent `error` handling.

    The function immediately returns upon receiving `n` non-falsy `result`
    values and calls the `done` callback with `null` as the first argument and
    `true` as the second argument.

    If all elements fail, the function calls the `done` callback with `null`
    as the first argument and `false` as the second argument.

    Execution is *not* guaranteed to be asynchronous. To guarantee asynchrony,
    wrap the `done` callback in a function which either executes at the end of
    the current stack (e.g., `nextTick`) or during a subsequent turn of the
    event loop (e.g., `setImmediate`, `setTimeout`).

    The function does not support dynamic collection resizing.

    The function does not skip `undefined` elements.

    Parameters
    ----------
    collection: Array|TypedArray|Object
        Input collection over which to iterate. If provided an object, the
        object must be array-like (excluding strings and functions).

    n: number
        Minimum number of successful elements.

    options: Object (optional)
        Function options.

    options.limit: integer (optional)
        Maximum number of pending invocations. Default: Infinity.

    options.series: boolean (optional)
        Boolean indicating whether to process each collection element
        sequentially. Default: false.

    options.thisArg: any (optional)
        Execution context.

    predicate: Function
        The test function to invoke for each element in a collection.

    done: Function
        A callback invoked either upon processing all collection elements or
        upon encountering an error.

    Examples
    --------
    // Basic usage:
    > function predicate( value, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, false );
    ...     }
    ... };
    > function done( error, bool ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( bool );
    ... };
    > var arr = [ 3000, 2500, 1000 ];
    > someByAsync( arr, 2, predicate, done )
    1000
    2500
    3000
    false

    // Limit number of concurrent invocations:
    > function predicate( value, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, false );
    ...     }
    ... };
    > function done( error, bool ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( bool );
    ... };
    > var opts = { 'limit': 2 };
    > var arr = [ 3000, 2500, 1000 ];
    > someByAsync( arr, 2, opts, predicate, done )
    2500
    3000
    1000
    false

    // Process sequentially:
    > function predicate( value, next ) {
    ...     setTimeout( onTimeout, value );
    ...     function onTimeout() {
    ...         console.log( value );
    ...         next( null, false );
    ...     }
    ... };
    > function done( error, bool ) {
    ...     if ( error ) {
    ...         throw error;
    ...     }
    ...     console.log( bool );
    ... };
    > var opts = { 'series': true };
    > var arr = [ 3000, 2500, 1000 ];
    > someByAsync( arr, 2, opts, predicate, done )
    3000
    2500
    1000
    false


